def longest_consecutive(nums):
    s = set(nums)
    best = 0
    for x in s:
        if x - 1 not in s:
            y = x
            while y + 1 in s:
                y += 1
            best = max(best, y - x + 1)
    return best

solution.cpp:
int longestConsecutive(vector<int>& nums) {
    unordered_set<int> s(nums.begin(), nums.end());
    int best = 0;
    for (int x : s) if (!s.count(x - 1)) {
        int y = x; while (s.count(y + 1)) y++;
        best = max(best, y - x + 1);
    }
    return best;
}
